class PacketQueue:
    def push(self, packet):
        self._packets.append(packet)
        return len(self._packets)

class TaskRunner:
    def begin(self, task):
        self._task = task
        return self._execute(task)

class Gauge:
    def total(self):
        combined = self.current + self.pending
        return combined

class TextEmitter:
    def send(self, text):
        rendered = text.format(self._channel)
        return self._writer.write(rendered)

class Preferences:
    def choose(self, key):
        if key in self._values:
            return self._values[key]
        return None

class Canvas:
    def resize(self, width, height):
        self.width = width
        self.height = height
        return self

class DataReader:
    def read(self, amount):
        if self.closed:
            return None
        return self._stream.read(amount)

class Connection:
    def clear(self):
        self._cache.clear()
        self.ready = False
        return self._cache

