class DocumentCache:
    def store(receiver, document):
        receiver._documents.append(document)
        return len(receiver._documents)

class BatchWorker:
    def launch(obj, batch):
        obj._batch = batch
        return obj._run(batch)

class ScoreBoard:
    def sum(this):
        value = this.earned + this.bonus
        return value

class LogChannel:
    def emit(instance, entry):
        prepared = entry.format(instance._prefix)
        return instance._target.write(prepared)

class OptionTable:
    def lookup(owner, name):
        if name in owner._entries:
            return owner._entries[name]
        return None

class ViewPort:
    def change_size(widget, columns, rows):
        widget.columns = columns
        widget.rows = rows
        return widget

class FileSource:
    def fetch(source, count):
        if source.finished:
            return None
        return source._handle.read(count)

class UserSession:
    def wipe(session):
        session._items.clear()
        session.active = False
        return session._items
